"""操作音效：点击 / 发送 / 唤醒等短提示音。

wav 文件由 scripts/gen_fx.py 生成到 fx/ 目录（QSoundEffect 播放本地音频）；
缺文件时静默跳过，不影响主流程。静音开关与 TTS 共用右键菜单的"静音"项。
"""
import os

from PySide6.QtCore import QUrl
from PySide6.QtMultimedia import QSoundEffect

FX_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fx")


class SoundFx:
    """轻量音效播放器。"""

    def __init__(self):
        self.muted = False
        self._effects = {}

    def _get(self, name: str):
        if name not in self._effects:
            fx = QSoundEffect()
            path = os.path.join(FX_DIR, name + ".wav")
            if os.path.exists(path):
                fx.setSource(QUrl.fromLocalFile(path))
                fx.setVolume(0.6)
            self._effects[name] = fx
        return self._effects[name]

    def play(self, name: str):
        if self.muted:
            return
        self._get(name).play()

    def set_muted(self, muted: bool):
        self.muted = muted

